32	const POLL_MS = 3000;
33	const MAX_ATTEMPTS = 3;
34	
35	// Customer per-server backup retention: keep only the latest N backups. Older
36	// ones are pruned after every successful backup so they never pile up.
37	const CUSTOMER_BACKUP_KEEP = 2;
38	
39	// Job types whose terminal failure genuinely leaves the VM in a bad/unknown
40	// run or disk state — only these should mark the server ERROR. Everything else
41	// (backup, snapshot-create, control-panel ops, SSL, migrate copy, game update…)
42	// is a side operation that doesn't touch the VM's run state.
43	const VM_STATE_FAILURE_JOBS = new Set<string>([
44	  "PROVISION", "REINSTALL", "DELETE", "RESIZE", "START", "STOP",
45	  "REBOOT", "SUSPEND", "UNSUSPEND", "BACKUP_RESTORE", "SNAPSHOT_ROLLBACK",
46	]);
47	
48	function generatePassword(): string {
49	  // URL-safe, no ambiguous chars, 16 chars
50	  return randomBytes(24).toString("base64url").replace(/[-_]/g, "x").slice(0, 16);
51	}
52	
53	async function loadServer(job: Job): Promise<Server & { plan: any; osTemplate: any; node: any }> {
54	  const server = await db.server.findUnique({
55	    where: { id: job.serverId! },
56	    include: { plan: true, osTemplate: true, node: true },
57	  });
58	  if (!server) throw new Error(`Server ${job.serverId} not found`);
59	  return server as any;
60	}
61	
62	/** Resolve the Proxmox client + node config for a server (falls back to the primary node). */
63	async function nodeFor(server: any) {
64	  const n =
65	    server.node ??
66	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
67	    (await db.node.findFirst({ where: { enabled: true } }));
68	  if (!n) {
69	    // No Node rows yet — use the env-configured primary via the global client.
70	    return { conn: { get: pve.get, post: pve.post, put: pve.put, del: pve.del, node, waitForTask, nextVmid, vmStatus: (v: number) => pve.get(`/nodes/${node}/qemu/${v}/status/current`) } as any, row: null };
71	  }
72	  return { conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }), row: n };
73	}
74	
75	/** YAML-safe indent of a multi-line script under a `content: |` block. */
76	function indentBlock(text: string, spaces: number): string {
77	  const pad = " ".repeat(spaces);
78	  return text.split("\n").map((l) => pad + l).join("\n");
79	}
80	
81	/**
82	 * Build a per-server cloud-init vendor snippet: guest agent + root SSH,
83	 * plus any control-panel/app install script and selected add-ons. Long installs
84	 * run in the background so the VM reports ready promptly.
85	 */
86	function buildCloudInit(server: any): string {
87	  const addons = (server.addons ?? {}) as {
88	    malwareScanner?: boolean;
89	    dailyBackup?: boolean;
90	    docker?: boolean;
91	    claudeCode?: boolean;
92	  };
93	  const setup: string[] = [];
94	
95	  // Pre-bake Claude Code (Anthropic CLI) on every server unless explicitly opted
96	  // out. Customers SSH in and run `claude` using their own subscription or API
97	  // key — no setup on our side, zero token cost to us. Installs run in the
98	  // background (nohup below) so the VM still reports ready quickly.
99	  if (addons.claudeCode !== false) {
100	    setup.push(
101	      "# --- Nxeon: pre-install Claude Code (Anthropic CLI) ---",
102	      "(apt-get install -y git curl ca-certificates || dnf install -y git curl ca-certificates || true)",
103	      "if ! command -v node >/dev/null 2>&1; then " +
104	        "(curl -fsSL https://deb.nodesource.com/setup_20.x | bash - && apt-get install -y nodejs) || " +
105	        "(curl -fsSL https://rpm.nodesource.com/setup_20.x | bash - && dnf install -y nodejs) || " +
106	        "(apt-get install -y nodejs npm || true); fi",
107	      "npm install -g @anthropic-ai/claude-code || true",
108	      "command -v claude >/dev/null 2>&1 && echo 'Claude Code installed' >> /var/log/nxeon-setup.log || true",
109	    );
110	  }
111	
112	  if (addons.docker) setup.push("curl -fsSL https://get.docker.com | sh && systemctl enable --now docker");
113	  if (addons.malwareScanner)
114	    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
115	  if (server.osTemplate.setupScript) setup.push(server.osTemplate.setupScript);
116	
117	  const script = ["#!/bin/bash", "set -x", ...setup].join("\n");
118	
119	  // A friendly first-login guide + MOTD banner pointing at the portal hub.
120	  const welcome = [
121	    "# Welcome to your Nxeon server",
122	    "",
123	    "## Build anything with Claude Code — it's already installed",
124	    "",
125	    "1. You're already logged in. Just run:",
126	    "",
127	    "   claude",
128	    "",
129	    "2. Sign in once — either with your Claude subscription (Pro/Max) or an",
130	    "   Anthropic API key. See the step-by-step guide with screenshots at:",
131	    "",
132	    "   https://nxeon.cloud/dashboard/claude-code",
133	    "",
134	    "3. Then describe what you want in plain English, for example:",
135	    '   "Build a modern website for my coffee shop with a menu and contact form,',
136	    '    then run it and tell me the URL to preview it."',
137	    "",
138	    "Copy-paste starter prompts (spa site, booking app, REST API, Discord bot,",
139	    "and 20+ more) and how-to guides live in your portal at the link above.",
140	    "",
141	    "Happy building!",
142	  ].join("\n");
143	
144	  const motd = [
145	    "#!/bin/sh",
146	    'if [ -t 1 ]; then',
147	    '  printf "\\n  \\033[1mNxeon\\033[0m — Claude Code is pre-installed on this server.\\n"',
148	    '  printf "  Run \\033[1mclaude\\033[0m to start building. Guide: https://nxeon.cloud/dashboard/claude-code\\n"',
149	    '  printf "  Full walkthrough: \\033[2m~/START-WITH-CLAUDE.md\\033[0m\\n\\n"',
150	    "fi",
151	  ].join("\n");
152	
153	  return `#cloud-config
154	package_update: true
155	packages:
156	  - qemu-guest-agent
157	ssh_pwauth: true
158	disable_root: false
159	write_files:
160	  - path: /etc/ssh/sshd_config.d/60-nxeon.conf
161	    permissions: "0644"
162	    content: |
163	      PermitRootLogin yes
164	      PasswordAuthentication yes
165	  - path: /root/START-WITH-CLAUDE.md
166	    permissions: "0644"
167	    content: |
168	${indentBlock(welcome, 6)}
169	  - path: /etc/profile.d/nxeon-welcome.sh
170	    permissions: "0755"
171	    content: |
172	${indentBlock(motd, 6)}
173	  - path: /root/nxeon-setup.sh
174	    permissions: "0755"
175	    content: |
176	${indentBlock(script, 6)}
177	runcmd:
178	  - systemctl enable --now qemu-guest-agent
179	  - systemctl restart ssh || systemctl restart sshd
180	  - nohup /root/nxeon-setup.sh > /var/log/nxeon-setup.log 2>&1 &
181	`;
182	}
183	
184	const SNIPPET_DIR = process.env.NXEON_SNIPPET_DIR ?? "/tank/backup/snippets";
185	const SNIPPET_STORAGE = process.env.NXEON_SNIPPET_STORAGE ?? "backup";
186	
187	async function provision(job: Job) {
188	  const server = await loadServer(job);
189	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING" } });
190	
191	  if (SANDBOX) {
192	    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
193	    // resize/start, no IPAM/OVH allocation, no cloud-init snippet write.
194	    const vmid = server.vmid ?? (990000 + (await db.server.count()));
195	    const password = generatePassword();
196	    const ip = sandboxIp(vmid);
197	    await db.server.update({
198	      where: { id: server.id },
199	      data: { vmid, ipAddress: ip, sshPort: null, rootPassword: null, rootPasswordEnc: encryptSecret(password), status: "RUNNING" },
200	    });
201	    await notify(
202	      server.userId,
203	      `Server ${server.hostname} is ready`,
204	      `Sandbox server provisioned (no real VM was created). ssh root@${ip}`,
205	      `/dashboard/servers/${server.id}`
206	    );
207	    return;
208	  }
209	
210	  const { conn, row: nodeRow } = await nodeFor(server);
211	  const storage = server.plan.storageTier === "hdd"
212	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
213	    : nodeRow?.storageNvme ?? "vmdata";
214	
215	  const vmid = server.vmid ?? (await conn.nextVmid());
216	  const password = generatePassword();
217	
218	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
219	  // Default: every new server pulls a dedicated IP from the pool; if the pool is
220	  // empty (or OVH isn't configured) it transparently falls back to shared NAT.
221	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
222	  const { getSettingBool: _settingBool } = await import("../lib/settings");
223	  const wantDedicated = server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
224	  if (wantDedicated && ovhConfigured()) {
225	    try {
226	      // Idempotent: on a PROVISION retry (VM may already exist) this returns the
227	      // server's already-ASSIGNED IP rather than claiming a second pool IP.
228	      dedicated = await allocateDedicatedIp(server.id, vmid);
229	    } catch (e) {
230	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
231	    }
232	  }
233	  // Node-aware + transactionally-claimed allocation (passing the server id enables
234	  // the claim path, so two concurrent provisions can't pick the same IP/port).
235	  const ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp(server.nodeId, server.id)));
236	  const sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort(server.nodeId, server.id)));
237	
238	  await db.server.update({
239	    where: { id: server.id },
240	    data: { vmid, ipAddress: ip, sshPort, rootPassword: null, rootPasswordEnc: encryptSecret(password) },
241	  });
242	
243	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
244	  // PROVISION must be re-runnable. `vmid` is persisted BEFORE the clone, so a retry
245	  // (worker restart mid-clone, or any transient failure in the steps below) would
246	  // re-issue a clone onto an id that now exists — Proxmox rejects it and all 3
247	  // attempts fail identically, stranding a half-built VM in ERROR. Everything after
248	  // the clone is idempotent, so skip it when the VM is already present.
249	  let vmAlreadyExists = false;
250	  try {
251	    await conn.vmStatus(vmid);
252	    vmAlreadyExists = true;
253	  } catch {
254	    vmAlreadyExists = false;
255	  }
256	  if (vmAlreadyExists) {
257	    console.log(`[worker] vm ${vmid} already exists — skipping clone (idempotent retry)`);
258	  } else {
259	    const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
260	      newid: vmid,
261	      name: server.hostname,
262	      full: 1,
263	      storage,
264	    });
