553	async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
554	  const server = await loadServer(job);
555	  const payload = (job.payload ?? {}) as { name?: string };
556	  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
557	  if (!name) throw new Error("snapshot: invalid name");
558	  if (SANDBOX) {
559	    await notify(
560	      server.userId,
561	      `Snapshot ${op} (sandbox): ${name}`,
562	      `Sandbox snapshot ${op} completed (no real VM was touched).`,
563	      `/dashboard/servers/${server.id}`
564	    );
565	    return;
566	  }
567	  const { conn } = await nodeFor(server);
568	  let upid: string;
569	  if (op === "create") {
570	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
571	  } else if (op === "delete") {
572	    upid = await conn.del(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}`);
573	  } else {
574	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
575	  }
576	  await conn.waitForTask(upid, 600_000);
577	  if (op === "rollback") {
578	    // rollback leaves the VM stopped; bring it back if the server should be running
579	    const current = await db.server.findUnique({ where: { id: server.id } });
580	    if (current?.status === "RUNNING") {
581	      try {
582	        const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
583	        await conn.waitForTask(startUpid);
584	      } catch { /* may already be running */ }
585	    }
586	  }
587	}
