665	async function backupCreate(job: Job) {
666	  const server = await loadServer(job);
667	  if (SANDBOX) {
668	    await sandboxAnimateJob(job.id, [
669	      { pct: 5, step: "Starting" },
670	      { pct: 25, step: "Creating archive… 25%" },
671	      { pct: 55, step: "Creating archive… 55%" },
672	      { pct: 80, step: "Creating archive… 80%" },
673	      { pct: 95, step: "Finalizing" },
674	      { pct: 100, step: "Backup complete" },
675	    ]);
676	    await notify(
677	      server.userId,
678	      `Backup completed (sandbox) for ${server.hostname}`,
679	      "Sandbox backup completed (no real VM was touched).",
680	      `/dashboard/servers/${server.id}`
681	    );
682	    return;
683	  }
684	  await reportJobProgress(job.id, 2, "Starting");
685	  const { conn } = await nodeFor(server);
686	  const upid = await conn.post(`/nodes/${conn.node}/vzdump`, {
687	    vmid: server.vmid,
688	    storage: "backup",
689	    mode: "snapshot",
690	    compress: "zstd",
691	  });
692	  await waitForTaskProgress(
693	    conn,
694	    upid,
695	    (progress, step) => reportJobProgress(job.id, progress, step),
696	    { timeoutMs: 3_600_000, phase: "backup" }
697	  );
698	  await reportJobProgress(job.id, 100, "Backup complete");
699	  // Retention: keep only the latest few backups for this server; prune the rest.
700	  if (server.vmid != null) {
701	    try {
702	      const pruned = await pruneBackups(conn, server.vmid, CUSTOMER_BACKUP_KEEP);
703	      if (pruned > 0) console.log(`[backup] pruned ${pruned} old backup(s) for vmid ${server.vmid} (keep ${CUSTOMER_BACKUP_KEEP})`);
704	    } catch (e) {
705	      console.error(`[backup] prune failed for vmid ${server.vmid}`, e);
706	    }
707	  }
708	  await notify(server.userId, `Backup completed for ${server.hostname}`, undefined,
709	    `/dashboard/servers/${server.id}`);
710	}
